INSERT INTO public.periods (id,label_fr,label_en,description_fr,description_en,wikidata_id,wikipedia_title_fr,wikipedia_title_en,start_date,end_date,start_years_bp,end_years_bp,non_thematic) VALUES
('bf06f8aa-ef1e-4975-ad28-0841890548a4','Jeunesse d’Alexandre en Macédoine','Alexander’s youth in Macedon','Fils de Philippe II, Alexandre a pour précepteur Aristote et commande la cavalerie macédonienne dès dix-huit ans.','The son of Philip II, Alexander is tutored by Aristotle and commands the Macedonian cavalry at eighteen.',NULL,NULL,NULL,'356 BCE','336 BCE',2381.81382614648,2361.81382614648,false),
('1d742c54-7b18-45f0-a8b5-913b3b3d40e7','Alexandre s’impose en Grèce','Alexander secures Greece','Devenu roi, Alexandre élimine ses rivaux, soumet les peuples du nord et rase Thèbes révoltée.','Once king, Alexander eliminates his rivals, subdues the northern peoples and razes rebellious Thebes.',NULL,NULL,NULL,'336 BCE','334 BCE',2361.81382614648,2359.81519507187,false),
('3cd34e6b-d287-4747-bad3-5060cd4e4ef7','Jeunesse et débuts politiques de César','Caesar’s youth and early career','Issu d’une vieille famille patricienne, César gravit les magistratures et devient grand pontife en 63 av. J.-C.','Born into an old patrician family, Caesar climbs the magistracies and becomes pontifex maximus in 63 BC.',NULL,NULL,NULL,'100 BCE','60 BCE',2125.82203969884,2085.82203969884,false),
('e1e7b161-06dc-482b-9dbf-95d5cad3758a','César, du triumvirat au consulat','Caesar from the triumvirate to the consulship','Allié à Pompée et à Crassus, César obtient le consulat puis le gouvernement des Gaules pour cinq ans.','Allied with Pompey and Crassus, Caesar gains the consulship and then the governorship of Gaul for five years.',NULL,NULL,NULL,'60 BCE','58 BCE',2085.82203969884,2083.82340862423,false),
('c3c5e09e-cda6-4273-b3a0-3ccc05cb93c1','Guerre civile de César','Caesar’s civil war','César affronte Pompée puis ses partisans en Grèce, en Égypte, en Afrique et en Espagne.','Caesar fights Pompey and then his supporters in Greece, Egypt, Africa and Spain.','Q1238338','Guerre civile de César','Caesar''s civil war','49 BCE','45 BCE',2074.82409308693,2070.82409308693,false),
('b694a20b-d1ae-42b9-8b1c-d0ea5da694c7','Dictature de César','Caesar’s dictatorship','Seul maître de Rome, César réforme le calendrier, agrandit le Sénat et fonde des colonies pour ses vétérans.','Sole master of Rome, Caesar reforms the calendar, enlarges the Senate and founds colonies for his veterans.',NULL,NULL,NULL,'45 BCE','-0043-03-15',2070.82409308693,2069.62217659138,false),
('446f0a39-10c2-4757-be9c-7f8ac5613a26','Jeunesse et premiers emplois de Confucius','Confucius’s youth and first posts','Orphelin de père, Confucius étudie les rites et tient de modestes emplois d’intendant dans le pays de Lu.','Having lost his father, Confucius studies the rites and holds minor stewardship posts in the state of Lu.',NULL,NULL,NULL,'551 BCE','522 BCE',2576.81177275838,2547.81245722108,false),
('4a7d7193-fe12-41d2-a1c3-6942b160f444','Confucius maître et fonctionnaire à Lu','Confucius as teacher and official in Lu','Confucius enseigne à des élèves de toutes origines et exerce, vers cinquante ans, des charges à la cour de Lu.','Confucius teaches pupils of all backgrounds and, at about fifty, holds office at the court of Lu.',NULL,NULL,NULL,'522 BCE','497 BCE',2547.81245722108,2522.81587953457,false),
('542ff4d4-52b1-4677-9f38-f625d36e4129','Années d’errance de Confucius','Confucius’s years of wandering','Avec ses disciples, Confucius va de principauté en principauté sans trouver de souverain qui applique ses conseils.','With his disciples, Confucius travels from state to state without finding a ruler willing to apply his advice.',NULL,NULL,NULL,'497 BCE','484 BCE',2522.81587953457,2509.81382614648,false),
('750d1cf1-6f00-4d71-ba42-e0d16cfbb5d7','Dernières années de Confucius à Lu','Confucius’s last years in Lu','De retour à Lu, Confucius se consacre à l’enseignement et, selon la tradition, à la mise en ordre des textes classiques.','Back in Lu, Confucius devotes himself to teaching and, according to tradition, to editing the classic texts.',NULL,NULL,NULL,'484 BCE','479 BCE',2509.81382614648,2504.81451060917,false),
('8785d056-1351-4edc-bdd0-3170995630c7','Jeunesse de Mahomet à La Mecque','Muhammad’s youth in Mecca','Orphelin élevé par son grand-père puis son oncle, Mahomet devient caravanier au service de Khadija, qu’il épouse.','An orphan raised by his grandfather and then his uncle, Muhammad becomes a caravan trader in the service of Khadija, whom he marries.',NULL,NULL,NULL,'0570','0610',1456.83367556468,1416.83641341547,false),
('fb37ab83-f1bb-4dd6-9d08-6c50bd1e721c','Jeunesse de Charlemagne','Charlemagne’s youth','Fils aîné de Pépin le Bref, Charles est sacré avec son père et son frère par le pape en 754 ; son année de naissance reste discutée.','The eldest son of Pepin the Short, Charles is anointed with his father and brother by the pope in 754; his year of birth is still debated.',NULL,NULL,NULL,'0748','0768-10-09',1278.84052019165,1258.06844626968,false),
('11196d7c-a4e6-4db3-adb9-6eee0a83605a','Guerres de Saxe','Saxon Wars','Trente ans de campagnes, de révoltes et de conversions forcées intègrent la Saxe au royaume franc.','Thirty years of campaigns, revolts and forced conversions bring Saxony into the Frankish kingdom.','Q499909','Guerre des Saxons','Saxon Wars','0772','0804',1254.84052019165,1222.84052019165,false),
('5cf38e79-0481-4774-902f-a663824ed783','Jeunesse et débuts de Galilée à Pise','Galileo’s youth and beginnings in Pisa','Galilée abandonne la médecine pour les mathématiques et obtient une chaire à l’université de Pise en 1589.','Galileo gives up medicine for mathematics and gains a chair at the University of Pisa in 1589.',NULL,NULL,NULL,'1564-02-15','1592',462.733744010951,434.856947296372,false),
('da9770ff-46d3-42df-a555-f2e0469fe45b','Galilée professeur à Padoue','Galileo as professor at Padua','Pendant dix-huit ans, Galilée enseigne à Padoue, étudie la chute des corps et perfectionne la lunette.','For eighteen years Galileo teaches at Padua, studies falling bodies and improves the telescope.',NULL,NULL,NULL,'1592','1610',434.856947296372,416.855578370979,false),
('34bd5b30-ef55-44e7-87e3-b143904426e5','Galilée à la cour des Médicis','Galileo at the Medici court','Mathématicien du grand-duc de Toscane, Galilée défend publiquement le mouvement de la Terre.','Mathematician to the Grand Duke of Tuscany, Galileo publicly defends the motion of the Earth.',NULL,NULL,NULL,'1610','1633',416.855578370979,393.854893908282,false),
('66c753c6-2737-41e4-ac4b-49ea25a113c3','Galilée assigné à résidence à Arcetri','Galileo under house arrest at Arcetri','Condamné, Galilée termine sa vie près de Florence, où il achève son traité de mécanique malgré la cécité.','After his sentence, Galileo ends his life near Florence, completing his treatise on mechanics despite going blind.',NULL,NULL,NULL,'1633','1642-01-08',393.854893908282,384.836413415469,false),
('9e8a4d1d-04e0-44b8-8e33-67ab118eb247','Minorité de Louis XIV et ministère de Mazarin','Minority of Louis XIV and Mazarin’s ministry','Anne d’Autriche exerce la régence et le cardinal Mazarin gouverne jusqu’à sa mort.','Anne of Austria acts as regent and Cardinal Mazarin governs until his death.',NULL,NULL,NULL,'1643-05-14','1661-03-09',383.492128678987,365.671457905544,false),
('cdff3f25-0f67-4df2-aad0-43dad55e171b','La Fronde','The Fronde','Parlementaires puis grands seigneurs se soulèvent contre Mazarin ; le jeune roi doit fuir Paris.','Magistrates and then great nobles rise against Mazarin; the young king has to flee Paris.','Q656186','Fronde (histoire)','The Fronde','1648','1653',378.856947296372,373.854893908282,false),
('f503a31f-b85e-421e-9c18-67b1d8e42529','Règne personnel de Louis XIV','Personal rule of Louis XIV','Louis XIV gouverne sans premier ministre, avec Colbert puis Louvois, et impose son autorité à la noblesse.','Louis XIV governs without a chief minister, with Colbert and then Louvois, and imposes his authority on the nobility.',NULL,NULL,NULL,'1661-03-09','1715-09-01',365.671457905544,311.19370294319,false),
('e2bda529-0ba2-4323-9816-5a0b0f0acd62','Jeunesse et études de Gandhi','Gandhi’s youth and studies','Né dans une famille de notables du Gujarat, Gandhi étudie le droit à Londres et devient avocat.','Born into a family of notables in Gujarat, Gandhi studies law in London and becomes a barrister.',NULL,NULL,NULL,'1869-10-02','1893',157.110198494182,133.860369609856,false),
('8b87d105-ef8c-4db7-ac09-2940bb6d171e','Gandhi en Afrique du Sud','Gandhi in South Africa','En défendant les droits des Indiens du Natal et du Transvaal, Gandhi met au point la résistance non violente, le satyagraha.','Defending the rights of Indians in Natal and the Transvaal, Gandhi develops non-violent resistance, satyagraha.',NULL,NULL,NULL,'1893','1915-01-09',133.860369609856,111.84257357974,false),
('39f64c1b-fff9-4bbf-be84-daee6a7d0951','Gandhi à la tête du mouvement national','Gandhi at the head of the national movement','Rentré en Inde, Gandhi fait du parti du Congrès un mouvement de masse et mène plusieurs campagnes de désobéissance civile.','Back in India, Gandhi turns the Congress party into a mass movement and leads several campaigns of civil disobedience.',NULL,NULL,NULL,'1915-01-09','1948-01-30',111.84257357974,78.7857631759069,false),
('fc10d303-11ae-46d5-87c2-5da0271c9090','Jeunesse et carrière militaire de Churchill','Churchill’s youth and military career','Officier et correspondant de guerre à Cuba, en Inde, au Soudan et en Afrique du Sud, Churchill se fait connaître par ses récits.','An officer and war correspondent in Cuba, India, Sudan and South Africa, Churchill makes his name through his writing.',NULL,NULL,NULL,'1874-11-30','1900-10',151.949349760438,126.11498973306,false),
('0bce18db-0ab1-4e31-8afe-dfc5278ad192','Churchill député et ministre','Churchill as MP and minister','Conservateur passé aux libéraux puis revenu aux conservateurs, Churchill occupe presque tous les grands ministères.','A Conservative who joins the Liberals and then returns to the Conservatives, Churchill holds almost every major ministry.',NULL,NULL,NULL,'1900-10','1929-06',126.11498973306,97.4496919917865,false),
('9eac3cfa-00d4-4ad3-8747-af424d9a1e59','Traversée du désert de Churchill','Churchill’s wilderness years','Écarté du gouvernement, Churchill écrit et dénonce le réarmement allemand et la politique d’apaisement.','Out of office, Churchill writes and denounces German rearmament and the policy of appeasement.',NULL,NULL,NULL,'1929-06','1939-09-03',97.4496919917865,87.1937029431896,false),
('c8c928c6-3647-49af-a13d-03ac0993feef','Churchill dans la Seconde Guerre mondiale','Churchill in the Second World War','Rappelé à l’Amirauté puis nommé Premier ministre, Churchill dirige l’effort de guerre britannique et l’alliance avec Roosevelt et Staline.','Recalled to the Admiralty and then appointed prime minister, Churchill leads the British war effort and the alliance with Roosevelt and Stalin.',NULL,NULL,NULL,'1939-09-03','1945-07-26',87.1937029431896,81.2991101984942,false),
('465adc83-a058-4bf2-bf39-2457a35d2ce7','Churchill après la guerre','Churchill after the war','Chef de l’opposition, de nouveau Premier ministre de 1951 à 1955, Churchill se retire ensuite de la vie publique.','Leader of the opposition, prime minister again from 1951 to 1955, Churchill then withdraws from public life.',NULL,NULL,NULL,'1945-07-26','1965-01-24',81.2991101984942,61.8001368925394,false),
('9b4d6e6e-9433-4100-a7df-c8d486290758','Jeunesse et carrière militaire de De Gaulle','De Gaulle’s youth and military career','Saint-cyrien, blessé et prisonnier pendant la Grande Guerre, de Gaulle plaide ensuite pour une armée de blindés.','A Saint-Cyr graduate, wounded and taken prisoner in the Great War, de Gaulle later argues for an armoured army.',NULL,NULL,NULL,'1890-11-22','1940-06-18',135.971252566735,86.4024640657084,false),
('92c71cc9-d37c-49b2-9435-d2fdaf4d5209','De Gaulle chef de la France libre','De Gaulle leader of Free France','Depuis Londres puis Alger, de Gaulle rassemble les forces qui continuent le combat et unifie la Résistance.','From London and then Algiers, de Gaulle gathers the forces that fight on and unifies the Resistance.',NULL,NULL,NULL,'1940-06-18','1944-08-25',86.4024640657084,82.2162902121834,false),
('80222909-e639-449f-9235-4ca1a7d9ac97','De Gaulle à la tête du Gouvernement provisoire','De Gaulle at the head of the Provisional Government','De Gaulle rétablit l’État, accorde le droit de vote aux femmes et lance les nationalisations et la Sécurité sociale.','De Gaulle restores the state, gives women the vote and launches nationalisations and social security.',NULL,NULL,NULL,'1944-08-25','1946-01-20',82.2162902121834,80.8117727583847,false),
('46d7de51-56d5-4adb-bb84-1e276d506f43','Traversée du désert de De Gaulle','De Gaulle’s years out of power','Opposé au régime des partis, de Gaulle fonde le RPF puis se retire à Colombey pour écrire ses Mémoires de guerre.','Opposed to party government, de Gaulle founds the RPF and then withdraws to Colombey to write his War Memoirs.',NULL,NULL,NULL,'1946-01-20','1958-06-01',80.8117727583847,68.4503764544832,false),
('92031400-2502-4910-9b6f-e29c0d390334','Retour de De Gaulle et fondation de la Ve République','De Gaulle’s return and the founding of the Fifth Republic','Rappelé pendant la crise algérienne, de Gaulle fait adopter une nouvelle Constitution par référendum.','Recalled during the Algerian crisis, de Gaulle has a new constitution adopted by referendum.',NULL,NULL,NULL,'1958-06-01','1959-01-08',68.4503764544832,67.845311430527,false),
('22e02b81-2a60-409b-90bc-1a253ed21bd6','Retraite de De Gaulle à Colombey','De Gaulle’s retirement at Colombey','De Gaulle se retire à la Boisserie et rédige ses Mémoires d’espoir, restés inachevés.','De Gaulle withdraws to La Boisserie and writes his Memoirs of Hope, left unfinished.',NULL,NULL,NULL,'1969-04-28','1970-11-09',57.5427789185489,56.009582477755,false);
INSERT INTO public.events (id,label_fr,label_en,description_fr,description_en,wikidata_id,wikipedia_title_fr,wikipedia_title_en,date,date_years_bp) VALUES
('ce26cf92-d7d9-4853-ad5c-43061d4358c3','Naissance d’Alexandre','Birth of Alexander','Alexandre naît à Pella, capitale du royaume de Macédoine.','Alexander is born at Pella, capital of the kingdom of Macedon.',NULL,NULL,NULL,'356 BCE',2381.81382614648),
('02a41e0f-1cd0-4f61-b2cc-3bf29dafdf20','Bataille de Chéronée','Battle of Chaeronea','Philippe II bat Athènes et Thèbes ; Alexandre, qui mène l’aile gauche, y gagne sa première grande victoire.','Philip II defeats Athens and Thebes; Alexander, leading the left wing, wins his first great victory.','Q200716','Bataille de Chéronée (338 av. J.-C.)','Battle of Chaeronea (338 BC)','338 BCE',2363.81519507187),
('892ca3e7-3535-45ef-9767-efc054b52772','Alexandre devient roi de Macédoine','Alexander becomes king of Macedon','Philippe II est assassiné lors d’une fête à Aigai ; l’armée acclame son fils, âgé de vingt ans.','Philip II is assassinated during a celebration at Aegae; the army acclaims his twenty-year-old son.',NULL,NULL,NULL,'336 BCE',2361.81382614648),
('2cdcfd58-4d86-4260-9a47-3266259849d9','Bataille du Granique','Battle of the Granicus','Première victoire sur les satrapes perses, qui ouvre à Alexandre l’Asie Mineure.','The first victory over the Persian satraps, opening Asia Minor to Alexander.','Q192938','Bataille du Granique','Battle of the Granicus','334 BCE',2359.81519507187),
('c997904d-21da-41fc-b98f-a2413baeba5f','Bataille d’Issos','Battle of Issus','Alexandre met en fuite le roi perse Darius III et capture sa famille.','Alexander puts the Persian king Darius III to flight and captures his family.','Q201526','Bataille d''Issos','Battle of Issus','333 BCE',2358.81587953457),
('f065e0f3-74d3-4e15-a0a9-1b57bf52cf14','Naissance de Jules César','Birth of Julius Caesar','César naît à Rome dans la gens Julia, qui prétend descendre de Vénus.','Caesar is born in Rome into the gens Julia, which claims descent from Venus.',NULL,NULL,NULL,'100 BCE',2125.82203969884),
('fa8df1c2-a84b-4b48-80a9-ed09bd9d3bde','Premier triumvirat','First Triumvirate','César, Pompée et Crassus s’entendent en secret pour se partager le pouvoir.','Caesar, Pompey and Crassus secretly agree to share power.','Q715380','Premier triumvirat','First Triumvirate','60 BCE',2085.82203969884),
('105fcb3e-040c-4257-bf8e-aa3d111c0dc7','Consulat de César','Caesar’s consulship','Consul, César fait voter une loi agraire en faveur des vétérans de Pompée malgré l’opposition du Sénat.','As consul, Caesar pushes through a land law for Pompey’s veterans despite the opposition of the Senate.',NULL,NULL,NULL,'59 BCE',2084.82272416153),
('eeee572b-87cc-4f3f-9e66-01308ca66389','Bataille de Pharsale','Battle of Pharsalus','En Thessalie, César écrase l’armée de Pompée, qui s’enfuit en Égypte où il est assassiné.','In Thessaly, Caesar crushes the army of Pompey, who flees to Egypt, where he is murdered.','Q203681','Bataille de Pharsale','Battle of Pharsalus','48 BCE',2073.82203969884),
('3c2a804b-7b6a-4414-b603-976235137e9e','César dictateur à vie','Caesar dictator for life','Le Sénat lui confère la dictature perpétuelle, ce qui précipite la conjuration.','The Senate grants him the dictatorship in perpetuity, which precipitates the conspiracy.',NULL,NULL,NULL,'44 BCE',2069.82203969884),
('eef6cede-fa7f-4d49-b034-a3e08e1df1a9','Confucius commence à enseigner','Confucius begins teaching','Vers trente ans, Confucius réunit ses premiers disciples ; la date est traditionnelle.','At about thirty, Confucius gathers his first disciples; the date is traditional.',NULL,NULL,NULL,'522 BCE',2547.81245722108),
('82e0454a-8a74-4888-ae09-2621da7a6487','Confucius ministre de la Justice de Lu','Confucius minister of justice of Lu','La tradition lui attribue cette charge à la cour du duc Ding ; les historiens discutent son importance réelle.','Tradition credits him with this office at the court of Duke Ding; historians debate how important it really was.',NULL,NULL,NULL,'500 BCE',2525.81382614648),
('eb483fc5-e0c1-4a3a-8ec2-f1f1da4a4e6b','Confucius quitte le pays de Lu','Confucius leaves the state of Lu','Déçu par le duc de Lu, Confucius part chercher ailleurs un prince à conseiller.','Disappointed by the duke of Lu, Confucius leaves to seek a prince to advise elsewhere.',NULL,NULL,NULL,'497 BCE',2522.81587953457),
('363f316d-8f8b-4c41-a8ec-9725d635ff86','Mort de Confucius','Death of Confucius','Confucius meurt à Qufu ; ses disciples rassembleront ses propos dans les Entretiens.','Confucius dies at Qufu; his disciples will gather his sayings in the Analects.',NULL,NULL,NULL,'479 BCE',2504.81451060917),
('2f85eb17-5f81-4645-851b-2205926c27e7','Naissance de Mahomet','Birth of Muhammad','La tradition place sa naissance à La Mecque vers 570, dans le clan des Banu Hachim.','Tradition places his birth in Mecca around 570, in the clan of Banu Hashim.',NULL,NULL,NULL,'0570',1456.83367556468),
('7049251c-68b4-411f-8b39-a6c03ff2f580','Première révélation','First revelation','Selon la tradition, Mahomet reçoit dans la grotte de Hira les premiers versets du Coran.','According to tradition, Muhammad receives the first verses of the Quran in the cave of Hira.',NULL,NULL,NULL,'0610',1416.83641341547),
('aced2c39-f010-4262-a44b-d624bfe9db1c','Bataille de Badr','Battle of Badr','Les musulmans de Médine remportent leur première victoire sur les Mecquois.','The Muslims of Medina win their first victory over the Meccans.','Q486124','Bataille de Badr','Battle of Badr','0624',1402.83778234086),
('5d7a3881-6d60-4ff7-b635-41ea1add0804','Bataille de Uhud','Battle of Uhud','Les Mecquois prennent leur revanche près de Médine ; Mahomet est blessé.','The Meccans take their revenge near Medina; Muhammad is wounded.','Q488278','Bataille de Uhud','Battle of Uhud','0625',1401.83572895277),
('8abc0292-24dd-40ae-98cd-0d2e472a1813','Bataille du Fossé','Battle of the Trench','Un fossé creusé autour de Médine fait échouer le siège mené par les Mecquois et leurs alliés.','A trench dug around Medina defeats the siege led by the Meccans and their allies.','Q826083','Bataille de la Tranchée','Battle of the Trench','0627',1399.83709787817),
('49d12f48-bc4e-4a3a-b8f7-55490cb91367','Traité d’Houdaybiya','Treaty of Hudaybiyyah','Une trêve de dix ans avec La Mecque autorise les musulmans à y venir en pèlerinage.','A ten-year truce with Mecca allows the Muslims to come there on pilgrimage.','Q1647162','Traité d''Houdaybiya','Treaty of al-Hudaybiya','0628',1398.83778234086),
('d8c6f4f0-50cd-4723-90d0-2e2ce456c1d5','Pèlerinage d’adieu','Farewell Pilgrimage','Mahomet accomplit son seul pèlerinage à La Mecque et y prononce un dernier sermon.','Muhammad makes his only pilgrimage to Mecca and delivers a last sermon there.','Q3352027','Pèlerinage d''adieu','Farewell Pilgrimage','0632',1394.83778234086),
('3ee323c7-3683-4349-811b-846b444d116e','Naissance de Charlemagne','Birth of Charlemagne','La date la plus souvent retenue aujourd’hui est 748 ; le lieu de naissance n’est pas connu.','The date most often accepted today is 748; the place of birth is unknown.',NULL,NULL,NULL,'0748',1278.84052019165),
('9bb6169d-6f2e-46d4-8824-4af2daa95793','Charlemagne seul roi des Francs','Charlemagne sole king of the Franks','La mort de son frère Carloman lui permet de réunir tout le royaume.','The death of his brother Carloman allows him to reunite the whole kingdom.',NULL,NULL,NULL,'0771-12',1254.92539356605),
('a63f20e8-6d40-4788-b98a-d3b0d21eae54','Prise de Pavie','Capture of Pavia','Après un long siège, Charlemagne prend la capitale lombarde et se proclame roi des Lombards.','After a long siege, Charlemagne takes the Lombard capital and proclaims himself king of the Lombards.','Q114717','Siège de Pavie (773-774)','Siege of Pavia (773–774)','0774-06',1252.4257357974),
('90451aea-1bd4-4a35-bc26-bebbe281b357','Bataille de Roncevaux','Battle of Roncevaux Pass','Au retour d’Espagne, l’arrière-garde franque est anéantie dans les Pyrénées par des Vascons ; l’épisode inspire la Chanson de Roland.','On the way back from Spain, the Frankish rearguard is wiped out in the Pyrenees by Basques; the episode inspires the Song of Roland.','Q1233475','Bataille de Roncevaux (778)','Battle of Roncevaux Pass','0778-08-15',1248.22039698836),
('01ab4d0e-30c9-4a78-bcf2-35df173a3253','Admonitio generalis','Admonitio generalis','Ce capitulaire règle la discipline du clergé et demande l’ouverture d’écoles dans les évêchés et les monastères.','This capitulary regulates clerical discipline and calls for schools in bishoprics and monasteries.','Q359314','Admonitio generalis','Admonitio generalis','0789',1237.83846680356),
('c871f398-6196-432f-a8ca-5b5beb7c50bb','Mort de Charlemagne','Death of Charlemagne','Charlemagne meurt à Aix-la-Chapelle, où il est inhumé dans la chapelle palatine.','Charlemagne dies at Aachen, where he is buried in the palace chapel.',NULL,NULL,NULL,'0814-01-28',1212.765229295),
('8eb79843-a712-456a-a7bf-ad96afebc72f','Naissance de Galilée','Birth of Galileo','Galilée naît à Pise ; son père, Vincenzo Galilei, est musicien et théoricien de la musique.','Galileo is born in Pisa; his father, Vincenzo Galilei, is a musician and music theorist.',NULL,NULL,NULL,'1564-02-15',462.733744010951),
('c8ad0d10-c102-4ce4-87bc-ea9cbb5d050a','Galilée tourne sa lunette vers le ciel','Galileo turns his telescope to the sky','Avec une lunette qu’il a perfectionnée, Galilée observe les reliefs de la Lune puis les satellites de Jupiter.','With a telescope he has improved, Galileo observes the mountains of the Moon and then the moons of Jupiter.',NULL,NULL,NULL,'1609',417.854893908282),
('b7489b83-d872-4b9c-ba24-4558f14e6917','L’Église condamne les thèses de Copernic','The Church condemns Copernican theory','Le livre de Copernic est mis à l’Index ; Galilée a été averti quelques jours plus tôt de ne plus défendre le mouvement de la Terre.','Copernicus’s book is placed on the Index; a few days earlier Galileo was warned no longer to defend the motion of the Earth.',NULL,NULL,NULL,'1616-03-05',410.681724845996),
('10eaa7d0-4257-4377-9a65-953357e62938','Dialogue sur les deux grands systèmes du monde','Dialogue Concerning the Two Chief World Systems','Sous la forme d’une conversation, Galilée compare les systèmes de Ptolémée et de Copernic, à l’avantage du second.','In the form of a conversation, Galileo compares the systems of Ptolemy and Copernicus, to the advantage of the latter.','Q1768303','Dialogue sur les deux grands systèmes du monde','Dialogue Concerning the Two Chief World Systems','1632',394.856947296372),
('f40feb95-9c43-4279-a6ce-fbfe7f24811f','Discours concernant deux sciences nouvelles','Two New Sciences','Publié à Leyde, l’ouvrage expose la résistance des matériaux et les lois du mouvement accéléré.','Published in Leiden, the work sets out the strength of materials and the laws of accelerated motion.','Q575461','Discours concernant deux sciences nouvelles','Two New Sciences','1638',388.855578370979),
('d7cad7ba-9723-4e26-9ace-a96d00048da3','Mort de Galilée','Death of Galileo','Galilée meurt à Arcetri ; l’Église lui refuse d’abord un tombeau monumental.','Galileo dies at Arcetri; the Church at first refuses him a monumental tomb.',NULL,NULL,NULL,'1642-01-08',384.836413415469),
('fc657fe1-1298-4a45-90f0-d9c5edb7a0bd','Naissance de Louis XIV','Birth of Louis XIV','Le futur roi naît à Saint-Germain-en-Laye après vingt-trois ans de mariage de ses parents.','The future king is born at Saint-Germain-en-Laye after his parents’ twenty-three years of marriage.',NULL,NULL,NULL,'1638-09-05',388.179329226557),
('fae2945b-5b43-4612-8d14-5a806c162c5e','Sacre de Louis XIV','Coronation of Louis XIV','Louis XIV est sacré à Reims, une fois la Fronde terminée.','Louis XIV is crowned at Reims once the Fronde is over.',NULL,NULL,NULL,'1654-06-07',372.425735797399),
('a013a190-9654-4cf0-8e49-1901112aad15','Mariage de Louis XIV et de Marie-Thérèse d’Autriche','Marriage of Louis XIV and Maria Theresa of Spain','Célébré à Saint-Jean-de-Luz, le mariage scelle la paix des Pyrénées avec l’Espagne.','Celebrated at Saint-Jean-de-Luz, the marriage seals the Peace of the Pyrenees with Spain.',NULL,NULL,NULL,'1660-06-09',366.418891170431),
('9c4172a6-ae3b-4c9c-99ee-66857abf9b14','Arrestation de Nicolas Fouquet','Arrest of Nicolas Fouquet','Le surintendant des finances est arrêté à Nantes par d’Artagnan ; le roi marque ainsi qu’il gouverne seul.','The superintendent of finances is arrested in Nantes by d’Artagnan; the king thereby shows that he rules alone.',NULL,NULL,NULL,'1661-09-05',365.17864476386),
('10bc933c-0020-4a3b-8c86-ff27f0a8740d','Mort de Louis XIV','Death of Louis XIV','Louis XIV meurt à Versailles ; son arrière-petit-fils, âgé de cinq ans, lui succède.','Louis XIV dies at Versailles; his five-year-old great-grandson succeeds him.',NULL,NULL,NULL,'1715-09-01',311.19370294319),
('3621b4d1-a523-4edb-b52a-59a6ead4bc27','Naissance de Gandhi','Birth of Gandhi','Mohandas Karamchand Gandhi naît à Porbandar, port du Gujarat.','Mohandas Karamchand Gandhi is born in Porbandar, a port in Gujarat.',NULL,NULL,NULL,'1869-10-02',157.110198494182),
('a774ba1a-81ae-4cc5-ab7b-e6cf1ca1f0f3','Mouvement de non-coopération','Non-cooperation movement','Gandhi appelle à boycotter les écoles, les tribunaux et les tissus britanniques ; il suspend la campagne en 1922 après des violences.','Gandhi calls for a boycott of British schools, courts and cloth; he suspends the campaign in 1922 after violence breaks out.','Q1479381','Mouvement de non-coopération','Non-cooperation movement (1919–1922)','1920-08-01',106.281998631075),
('d4ac5dd6-cd74-4ad3-b6f9-4f8cff664ba1','Quit India','Quit India Movement','Le Congrès exige le départ immédiat des Britanniques ; Gandhi et ses dirigeants sont arrêtés le lendemain.','Congress demands the immediate departure of the British; Gandhi and its leaders are arrested the next day.','Q1992677','Quit India','Quit India Movement','1942-08-08',84.2642026009582),
('83cebaa1-9267-4aad-96af-d77d1cfba619','Naissance de Winston Churchill','Birth of Winston Churchill','Churchill naît au palais de Blenheim, résidence des ducs de Marlborough, ses ancêtres.','Churchill is born at Blenheim Palace, seat of his ancestors the dukes of Marlborough.',NULL,NULL,NULL,'1874-11-30',151.949349760438),
('14b1da22-758a-48a9-8bb4-4797f6b339f5','Churchill élu député','Churchill elected to Parliament','Auréolé de son évasion pendant la guerre des Boers, Churchill est élu député conservateur d’Oldham.','Fresh from his escape during the Boer War, Churchill is elected Conservative MP for Oldham.',NULL,NULL,NULL,'1900-10',126.11498973306),
('0bf1f70f-18e8-4461-b030-1286f99086ab','Churchill chancelier de l’Échiquier','Churchill Chancellor of the Exchequer','Ministre des Finances, Churchill rétablit en 1925 la convertibilité de la livre en or.','As finance minister, Churchill restores the gold standard for the pound in 1925.',NULL,NULL,NULL,'1924-11-06',102.016427104723),
('5e315854-2f49-42d5-94c0-3aab0f0c71c3','Défaite électorale de Churchill','Churchill’s election defeat','Les travaillistes de Clement Attlee l’emportent largement ; Churchill quitte le pouvoir avant la fin de la guerre contre le Japon.','Clement Attlee’s Labour Party wins by a landslide; Churchill leaves office before the end of the war against Japan.','Q918397','Élections générales britanniques de 1945','1945 United Kingdom general election','1945-07-26',81.2991101984942),
('c073cbcb-24bb-49d0-af4d-48e7fd077a06','Discours de Fulton','Fulton speech','Dans le Missouri, Churchill déclare qu’un « rideau de fer » est tombé sur l’Europe.','In Missouri, Churchill declares that an “iron curtain” has descended across Europe.','Q2102143','Discours de Fulton','Fulton Speech','1946-03-05',80.6913073237509),
('88a39956-7ced-4121-be86-6254e91f02b9','Churchill de nouveau Premier ministre','Churchill prime minister again','À soixante-seize ans, Churchill retrouve le pouvoir après la victoire des conservateurs.','At seventy-six, Churchill returns to power after the Conservative victory.',NULL,NULL,NULL,'1951-10-26',75.0485968514716),
('0c065471-cca3-47d3-9e96-42eb05aa4730','Prix Nobel de littérature de Churchill','Churchill’s Nobel Prize in Literature','Le prix récompense ses ouvrages historiques et biographiques et son art oratoire.','The prize rewards his historical and biographical works and his oratory.',NULL,NULL,NULL,'1953-12-10',72.9240246406571),
('86257cfe-4286-4067-aa36-94858d5c68a7','Mort de Winston Churchill','Death of Winston Churchill','Churchill meurt à Londres à quatre-vingt-dix ans et reçoit des funérailles nationales.','Churchill dies in London aged ninety and is given a state funeral.',NULL,NULL,NULL,'1965-01-24',61.8001368925394),
('84a953b7-edc0-46a0-8a0a-92ff0395506f','Naissance de Charles de Gaulle','Birth of Charles de Gaulle','De Gaulle naît à Lille dans une famille catholique et lettrée.','De Gaulle is born in Lille into a Catholic, well-read family.',NULL,NULL,NULL,'1890-11-22',135.971252566735),
('e434a54e-7e0e-4868-90c4-74cc67c83b29','Discours de Bayeux','Bayeux speech','De Gaulle y expose les institutions qu’il souhaite : un chef de l’État fort, au-dessus des partis.','De Gaulle sets out the institutions he wants: a strong head of state, above the parties.',NULL,NULL,NULL,'1946-06-16',80.4093086926762),
('9f5ba9a4-2540-453e-a07f-3615cbaefc70','De Gaulle investi président du Conseil','De Gaulle invested as prime minister','Après le soulèvement d’Alger du 13 mai, l’Assemblée nationale lui confie le gouvernement et les pleins pouvoirs pour six mois.','After the Algiers uprising of 13 May, the National Assembly entrusts him with the government and full powers for six months.',NULL,NULL,NULL,'1958-06-01',68.4503764544832),
('bdea3b79-ecac-4cbb-80f1-03fa97d11d7d','Attentat du Petit-Clamart','Petit-Clamart attack','Un commando de l’OAS mitraille la voiture du général, qui en sort indemne.','An OAS commando machine-guns the general’s car; he emerges unharmed.','Q757982','Attentat du Petit-Clamart','Petit-Clamart attack','1962-08-22',64.2258726899384),
('96aff07b-4677-4917-aa7a-37355cc9e411','De Gaulle réélu au suffrage universel','De Gaulle re-elected by universal suffrage','Mis en ballottage, de Gaulle l’emporte au second tour sur François Mitterrand.','Forced into a run-off, de Gaulle wins the second round against François Mitterrand.','Q1450635','Élection présidentielle française de 1965','1965 French presidential election','1965-12-19',60.8993839835729),
('3987c600-b643-4d73-93f7-47d2b9f59ac1','Démission de De Gaulle','De Gaulle’s resignation','Désavoué par le référendum sur le Sénat et les régions, de Gaulle quitte ses fonctions le lendemain du vote.','Defeated in the referendum on the Senate and the regions, de Gaulle leaves office the day after the vote.',NULL,NULL,NULL,'1969-04-28',57.5427789185489),
('9550b523-9d48-443d-841c-73a54ea1b671','Mort de Charles de Gaulle','Death of Charles de Gaulle','De Gaulle meurt à Colombey-les-Deux-Églises, où il est inhumé sans cérémonie officielle.','De Gaulle dies at Colombey-les-Deux-Églises, where he is buried without official ceremony.',NULL,NULL,NULL,'1970-11-09',56.009582477755);
